#include <stdio.h>

int main(void) {
    FILE *file = fopen("greeting.txt", "w");   // "w" = write mode

    if (file == NULL) {
        printf("Could not open file for writing.\n");
        return 1;
    }

    fprintf(file, "Hello, file!\n");
    fclose(file);

    printf("Wrote greeting.txt\n");
    return 0;
}
